CREATE OR REPLACE FUNCTION public.estruturar_projeto_pessoal(item uuid,respostas text[],etapas jsonb) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE dono uuid; area uuid; BEGIN IF NOT public.account_active() THEN RAISE EXCEPTION 'Conta inativa'; END IF; SELECT user_id,area_id INTO dono,area FROM public.itens WHERE id=item AND user_id=auth.uid() FOR UPDATE; IF dono IS NULL THEN RAISE EXCEPTION 'Item não encontrado'; END IF; IF cardinality(respostas)>5 OR jsonb_array_length(etapas)>8 THEN RAISE EXCEPTION 'Limites inválidos'; END IF; UPDATE public.itens SET tipo='projeto',status='em andamento',conteudo=conteudo||E'\n\n'||array_to_string(respostas,E'\n') WHERE id=item AND user_id=dono; INSERT INTO public.itens(user_id,titulo,conteudo,tipo,projeto_id,area_id,origem) SELECT dono,e->>'titulo',e->>'conteudo','atividade',item,area,'manual' FROM jsonb_array_elements(etapas) e; END $$; REVOKE ALL ON FUNCTION public.estruturar_projeto_pessoal(uuid,text[],jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.estruturar_projeto_pessoal(uuid,text[],jsonb) TO authenticated;